'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),crypto=require('node:crypto');
const root=path.resolve(__dirname,'..'),read=f=>fs.readFileSync(path.join(root,f),'utf8');
const invite=read('engines/swimmer-invite-bn.js'),portal=read('swimmer-portal.js'),sql=read('supabase/20260824_secure_swimmer_portal.sql'),qr=read('vendor/qrcode.min.js');
assert.doesNotMatch(invite,/cdn\.jsdelivr|unpkg|cdnjs/i,'QR generation must not depend on a third-party CDN');
assert.match(invite,/vendor\/qrcode\.min\.js\?v=20260907a/,'invite owner must load the bundled QR renderer');
assert.doesNotMatch(invite,/date_of_birth\s*:/,'published swimmer payload must not include DOB');
assert.match(invite,/projectionForSession/,'old-session preview must project directly from the selected canonical session');
assert.match(invite,/coachPreview/,'coach preview route must be explicit');
assert.match(invite,/p_minutes:15/,'real invite must remain 15 minutes');
assert.match(portal,/PREVIEW=PARAMS\.get\('coachPreview'\)==='1'/);
assert.match(portal,/if\(PREVIEW\)throw new Error\('Coach preview is read-only\. Nothing was sent\.'/,'preview RPC writes must fail closed');
assert.match(portal,/if\(PREVIEW\)\{startPreview\(\);return;\}/,'preview must exit before device-token/localStorage boot');
assert.match(portal,/e\.origin!==origin\|\|e\.source!==source/,'preview payload must be same-origin and opener-bound');
assert.match(sql,/consumed_at\s+is\s+null/i);assert.match(sql,/expires_at\s*>\s*now\(\)/i);assert.match(sql,/for update/i);assert.match(sql,/digest\(p_invite_token,\s*'sha256'\)/i);assert.match(sql,/consumed_at\s*=\s*now\(\)/i);
const old={id:'old-session',identity:{date:'2026-08-15',dayPart:'PM',slot:'PM',course:'SCM',squads:['National']},title:'Old test'},live={id:'live-session',identity:{date:'2026-09-07',dayPart:'PM',slot:'PM',course:'SCM',squads:['National']},title:'Tonight'},athlete={id:'matthew',full_name:'Matthew Test',preferred_name:'Matthew',squad:'National',date_of_birth:'2010-01-01'};
const state={settings:{selectedAthleteId:athlete.id,selectedSessionId:live.id},athletes:[athlete],canonicalSessions:{[old.id]:old,[live.id]:live},attendance:[],attendanceSnapshots:{},athleteSessionBoundaries:[],squadSessionBoundaries:[],adaptationOverrides:[],captures:[],trainingTestResults:[],meetEntries:[]};
const M={ui:{},state,access:{sessionAllowed:()=>true,role:()=> 'owner'},util:{escape:String},store:{config:()=>({}),auth:()=>({})},currentSession:()=>live,swimmerTrainingBG:{viewFor:()=>({week:{},month:{},upcoming:[]})}};
global.MSOS4=M;global.MSOSEngines={Coordinator:{prescription:(s,item)=>({item,target:{status:'none'}})}};global.MSOSArchitecture={AthleteReport:{athleteSessionProjection:({session,athlete})=>({date:session.identity.date,title:session.title,course:session.identity.course,squad:athlete.squad,delivery:'planned',metres:{recorded:0,current:1200,prescribed:1200},zones:{},strokes:{},tags:{},blocks:[{id:'main',label:'Main',metres:1200,items:[{id:'set-1',label:'6 x 100 Free',metres:600,tags:[],target:{status:'ok',seconds:70,sendOff:80}}]}]})}};global.document={readyState:'loading',addEventListener:()=>{}};global.requestAnimationFrame=()=>{};
vm.runInThisContext(invite,{filename:'swimmer-invite-bn.js'});
const payload=M.swimmerInviteBN.payloadFor(athlete,old);assert.equal(payload.session.id,old.id);assert.equal(payload.session.date,'2026-08-15');assert.equal(state.settings.selectedSessionId,live.id,'previewing an old session must not change live selected Training session');assert.equal(payload.athlete.full_name,'Matthew Test');assert.equal(Object.hasOwn(payload.athlete,'date_of_birth'),false);assert.equal(payload.session.blocks[0].items[0].label,'6 x 100 Free');assert.deepEqual(M.swimmerInviteBN.sessionsFor(athlete).map(s=>s.id),[live.id,old.id]);
const QR=require(path.join(root,'vendor/qrcode.min.js'));const url='https://andymclay5-web.github.io/McLay-Swimming-OS/swimmer-portal.html?invite='+'a'.repeat(64),matrix=QR._matrix(url),bits=matrix.map(r=>r.map(x=>x?'1':'0').join('')).join('\n');assert.equal(matrix.length,49);assert.equal(crypto.createHash('sha256').update(bits).digest('hex'),'e0dab28bb09a51227681c8a2dd24b687a07c10e4e4f9a3accdb6752d06462f46');
